WITH base AS (SELECT *, CONCAT_WS('-', country, city) AS country_city_key FROM suppliers WHERE city IS DISTINCT FROM 'Bangkok' AND city IN ('Tokyo', 'New York')), eligible AS (SELECT s.* FROM base s WHERE NOT EXISTS (SELECT 1 FROM products x WHERE x.supplier_id = s.id AND SIZE(x.tags) >= 1)), enriched AS (SELECT *, LEAD(rating) OVER w_grp AS next_rating, LAG(rating) OVER w_grp AS prev_rating, ROW_NUMBER() OVER w_grp AS row_seq FROM eligible WINDOW w_grp AS (PARTITION BY city, country ORDER BY rating, id)), filtered AS (SELECT id, supplier_name, city, rating, country_city_key, prev_rating, CASE WHEN country = 'TH' THEN 1 ELSE 0 END AS is_th, COALESCE(city, 'NONE') AS city_clean FROM enriched WHERE city IS DISTINCT FROM 'Chiang Mai' AND city IN ('New York', 'Tokyo', 'Berlin')) SELECT * FROM (SELECT id, city, rating, prev_rating FROM filtered) src UNPIVOT INCLUDE NULLS (metric_value FOR kpi IN (rating, prev_rating AS PREV_RATING))
